// Optional, bounded checks: one attempt per decision, with keyboard-friendly buttons.
const SCENARIOS=[
 {title:'Cross-map trade',lane:'TOP',enemy:'Five enemies show TOP. Baron is gone. Your bot wave is at their tower.',objective:'BOT TOWER',choices:['Trade bot tower','Walk into top river','Wait at base'],answer:0},
 {title:'River numbers',lane:'MID',enemy:'Two opponents are down for 25 seconds. All five allies are near dragon.',objective:'DRAGON',choices:['Recall together','Secure dragon now','Chase into their base'],answer:1},
 {title:'Protect the carry',lane:'BOT',enemy:'Your carry has no Flash. The enemy jungler disappears toward bot.',objective:'BOT COVER',choices:['Invade alone','Force Baron','Cover bot and place vision'],answer:2},
 {title:'Reset window',lane:'MID',enemy:'Your team has low health and unspent gold. Dragon spawns in 70 seconds.',objective:'RESET',choices:['Reset and buy together','Start a low-health fight','Split across enemy jungle'],answer:0},
 {title:'Catch the wave',lane:'TOP',enemy:'Baron is down. A huge wave hits your top inhibitor; all enemies are visible mid.',objective:'TOP WAVE',choices:['Ignore the wave','Send one to defend top','Send all five into river'],answer:1},
 {title:'Avoid the trap',lane:'BOT',enemy:'Three enemies are missing. Your support is alone beside an unwarded dragon pit.',objective:'VISION',choices:['Face-check alone','Blindly start dragon','Wait for allies and sweep'],answer:2},
 {title:'Teleport advantage',lane:'TOP',enemy:'Your top laner has Teleport. Their top laner used it. Dragon spawns in 40 seconds.',objective:'NUMBERS',choices:['Force a top duel','Push top then teleport to dragon','Ignore dragon vision'],answer:1},
 {title:'Baron bait',lane:'MID',enemy:'You have vision control and the enemy jungler is dead. Two enemies approach through one narrow corridor.',objective:'TURN',choices:['Turn together on the corridor','Split up and chase','Send your carry to face-check'],answer:0},
 {title:'Respect the reset',lane:'BOT',enemy:'Your carry recalled with a huge purchase available. The opponent has five players in river now.',objective:'TEMPO',choices:['Fight before your carry returns','Send support alone','Concede river until the reset completes'],answer:2},
 {title:'Open base',lane:'TOP',enemy:'Four enemies chase your tank in top lane. Your four teammates and a wave are at their exposed nexus towers.',objective:'END',choices:['Recall to help the tank','Commit to the exposed base','Walk toward dragon'],answer:1},
 {title:'Soul point setup',lane:'BOT',enemy:'Dragon spawns in 35 seconds. Mid wave is pushed toward you, and bot river is dark.',objective:'SETUP',choices:['Clear mid together and establish vision','Start a top-side chase','Wait alone in the pit'],answer:0},
 {title:'Winning split push',lane:'TOP',enemy:'Your split pusher wins the side-lane duel. The other four allies can safely defend mid.',objective:'SIDELANE',choices:['Force a risky four-versus-five','Send everyone top','Hold mid and let side pressure build'],answer:2}

];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={timing:'Objective timing',reaction:'Flash reaction',map:'Map read'};
export function mountSkillCheck(s,E,dialog,{save,resolve}){
 const c=s.match?.current?.skillCheck;if(!c)return;
 let timer=0,frame=0,stopped=false,start=0,cue=0;
 const clear=()=>{clearTimeout(timer);cancelAnimationFrame(frame);};
 const finish=value=>{if(stopped)return;stopped=true;clear();E.finishSkillCheck(s,value);save();draw();};
 const close=()=>{if(c.status==='attempted')finish(false);clear();dialog.removeEventListener('close',close);dialog.removeEventListener('cancel',close);};
 dialog.addEventListener('close',close);dialog.addEventListener('cancel',close);
 if(c.status==='attempted'){E.finishSkillCheck(s,NaN);save();}
 const instructions={timing:'Stop the marker inside the orange zone. Your proposing player’s Mechanics widens the zone.',reaction:'Wait for the action cue, then press the button. Pressing early or on a HOLD feint fails the check. Mechanics adds a little reaction-time allowance.',map:'Study the map briefing for four seconds, then choose the strongest response. You have ten seconds to answer.'};
 function draw(){dialog.innerHTML=`<div class="panelhead"><h2>${esc(c.title||names[c.type])}</h2><button id="check-close" aria-label="Close skill check">✕</button></div><div class="modalbody skillcheck"><div class="agentnote"><b>${c.replacement?'Player leading the moment':'Chosen call'} · ${esc(E.callPreview(s,c.kind).player.name)}</b><p>${c.replacement?'A live execution moment replaces the tactical calls.': '“'+esc(E.callPreview(s,c.kind).call[1])+'”'}</p></div><p>${instructions[c.type]}</p><p class="checkstakes">${c.replacement?'Success: +'+E.callPreview(s,c.kind).up.toFixed(1)+' result points. Miss: −'+E.callPreview(s,c.kind).down.toFixed(1)+' points. Trusting the players resolves from their abilities.':'Optional · success +6 percentage points · miss −3 points to this call’s success chance.'}</p><div id="check-stage"></div></div>`;dialog.querySelector('#check-close').onclick=()=>dialog.close();const stage=dialog.querySelector('#check-stage');
 if(c.status==='complete'){stage.innerHTML=`<h3>${c.result}</h3><p>${c.replacement?'Your execution directly decides this moment’s result points. The whole match still depends on both teams.':'The modifier applies only to this decision. It does not guarantee the play succeeds.'}</p><button class="primary" id="check-resolve">Resolve the moment →</button>`;stage.querySelector('button').onclick=()=>{close();dialog.close();resolve(c.kind);};return;}
 stage.innerHTML='<div class="actions"><button class="primary" id="check-start">Start check</button><button id="check-trust">Trust the players</button></div>';
 stage.querySelector('#check-trust').onclick=()=>{close();dialog.close();resolve(c.kind);};
 stage.querySelector('#check-start').onclick=()=>{if(!E.startSkillCheck(s))return;save();stopped=false;
 if(c.type==='timing'){const width=2*(.075+c.mechanics*.0007)*100,target=(c.target??.5)*100,duration=c.duration||2200;stage.innerHTML=`<div class="timingtrack"><div class="timingzone" style="left:${target-width/2}%;width:${width}%"></div><i id="timing-marker"></i></div><button class="primary checkhit">${esc(c.title||'Secure objective')}</button>`;start=performance.now();const animate=()=>{const elapsed=Math.min(1,(performance.now()-start)/duration),position=c.reverse?1-elapsed:elapsed;stage.querySelector('#timing-marker').style.left=position*100+'%';if(elapsed<1)frame=requestAnimationFrame(animate);else finish(NaN);};frame=requestAnimationFrame(animate);const hit=stage.querySelector('button');hit.focus();hit.onclick=()=>finish(c.reverse?1-(performance.now()-start)/duration:(performance.now()-start)/duration);}
 else if(c.type==='reaction'){stage.innerHTML='<button class="reactioncue checkhit">Wait for the cue…</button>';const hit=stage.querySelector('button');hit.focus();hit.onclick=()=>finish(cue?performance.now()-cue:-1);const trigger=()=>{cue=performance.now();hit.textContent=['FLASH NOW','DODGE NOW','SIDESTEP NOW','ESCAPE NOW'][c.variant||0];hit.classList.add('ready');timer=setTimeout(()=>finish(NaN),1800);};timer=setTimeout(()=>{if((c.variant||0)>=2){hit.textContent='HOLD — FEINT';timer=setTimeout(trigger,450+Math.random()*600);}else trigger();},850+Math.random()*1500);}
 else{const q=SCENARIOS[c.scenario],spot={TOP:[70,25],MID:[110,85],BOT:[195,115]}[q.lane];stage.innerHTML=`<div class="mapbrief"><svg viewBox="0 0 220 170" role="img" aria-label="Map briefing: pressure at ${q.lane}"><rect x="5" y="5" width="210" height="160" rx="8" fill="#465955"/><path d="M25 145 V25 H195 M25 145 H195 V25 M25 145 L195 25" fill="none" stroke="#88958b" stroke-width="9"/><path d="M20 65 Q110 110 200 105" fill="none" stroke="#638999" stroke-width="10"/><circle cx="25" cy="145" r="12" fill="#e08443"/><circle cx="195" cy="25" r="12" fill="#a44343"/><circle cx="${spot[0]}" cy="${spot[1]}" r="15" fill="#a44343" stroke="#f4cbb6" stroke-width="2"/><text x="${spot[0]}" y="${spot[1]+4}" text-anchor="middle" fill="#fff" font-size="13">!</text><circle cx="85" cy="110" r="7" fill="#e08443"/><circle cx="65" cy="125" r="7" fill="#e08443"/><text x="15" y="18" fill="#fff" font-size="12">TOP</text><text x="93" y="77" fill="#fff" font-size="12">MID</text><text x="172" y="158" fill="#fff" font-size="12">BOT</text></svg><div><h3>${q.title}</h3><p>${q.enemy}</p><b>Focus: ${q.lane} side</b></div></div><p>Remember the situation…</p>`;timer=setTimeout(()=>{stage.innerHTML=`<h3>What is the best response?</h3><div class="mapanswers">${q.choices.map((x,i)=>({x,i})).sort((a,b)=>((a.i+(c.variant||0))%3)-((b.i+(c.variant||0))%3)).map(({x,i})=>`<button data-answer="${i}">${x}</button>`).join('')}</div>`;stage.querySelectorAll('button').forEach(b=>b.onclick=()=>finish(Number(b.dataset.answer)===q.answer));stage.querySelector('button').focus();timer=setTimeout(()=>finish(false),10000);},4000);}
 };
 }
 draw();if(!dialog.open)dialog.showModal();
}
